void MeshClass::Make_Unique(bool force)
{
	// Copy the shared model when another mesh also uses it (or when asked).
	if (Model->Num_Refs() != 1 || force) {
		MeshModelClass *newmodel = new MeshModelClass(*Model);
		if (newmodel != NULL)
			newmodel->Add_Ref();
		if (Model != NULL)
			Model->Release_Ref();
		Model = newmodel;
		if (newmodel != NULL)
			newmodel->Release_Ref();
	}
}

// FUNCTION: BFME2 0x00149CC0 size=606 name=?Load_W3D@MeshClass@@QAE_NAAVChunkLoadClass@@@Z evidence=N:ledger tier=A
bool MeshClass::Load_W3D(ChunkLoadClass &cload)
{
	// Make sure this mesh is "empty"
	Free();

	// Create an empty model.
	Model = new MeshModelClass();
	if (Model == NULL) {
		return false;
	}

	// Create and read in the model.
	if (!Model->Load_W3D(cload)) {
		Free();
		return false;
	}

	// Pull interesting stuff out of the w3d attributes bits
	int col_bits = (Model->W3dAttributes & W3D_MESH_FLAG_COLLISION_TYPE_MASK) >> W3D_MESH_FLAG_COLLISION_TYPE_SHIFT;
	Set_Collision_Type(col_bits << 1);
	Set_Hidden(Model->W3dAttributes & W3D_MESH_FLAG_HIDDEN);

	// The mesh is translucent if sorting is enabled or pass 0 alpha-tests.
	int is_translucent = Model->Get_Flag(MeshModelClass::SORT);
	int is_alpha = 0;
	int is_additive = 0;
	if (Model->Has_Shader_Array(0)) {
		for (int i = 0; i < Model->Get_Polygon_Count(); i++) {
			ShaderClass shader = Model->Get_Shader(i, 0);
			is_translucent |= (shader.Get_Alpha_Test() == ShaderClass::ALPHATEST_ENABLE);
			is_alpha |= (shader.Get_Dst_Blend_Func() != ShaderClass::DSTBLEND_ZERO ||
				shader.Get_Src_Blend_Func() != ShaderClass::SRCBLEND_ONE) && (shader.Get_Alpha_Test() != ShaderClass::ALPHATEST_ENABLE);
			is_additive |= (shader.Get_Dst_Blend_Func() == ShaderClass::DSTBLEND_ONE &&
				shader.Get_Src_Blend_Func() == ShaderClass::SRCBLEND_ONE);
		}
	} else if (Model->Has_Pass_Buffer(0)) {
		is_translucent = 0;
		is_alpha = 0;
		is_additive = 0;
	} else {
		ShaderClass shader = Model->Get_Single_Shader(0);
		is_translucent |= (shader.Get_Alpha_Test() == ShaderClass::ALPHATEST_ENABLE);
		is_alpha |= (shader.Get_Dst_Blend_Func() != ShaderClass::DSTBLEND_ZERO ||
			shader.Get_Src_Blend_Func() != ShaderClass::SRCBLEND_ONE) && (shader.Get_Alpha_Test() != ShaderClass::ALPHATEST_ENABLE);
		is_additive |= (shader.Get_Dst_Blend_Func() == ShaderClass::DSTBLEND_ONE &&
			shader.Get_Src_Blend_Func() == ShaderClass::SRCBLEND_ONE);
	}
	// Retail's slots 109, 111 and 119 take the translucent, alpha and additive results (bits 0x40000, 0x400000,
	// 0x01000000: Zero Hour's three flags shifted left by four). The header names those slots after the Zero Hour order
	// (Zero Hour flags shifted left by four bits: translucent 0x40000, alpha 0x400000, additive 0x01000000; m03 pair)
	Set_Translucent(is_translucent);
	Set_Alpha(is_alpha);
	Set_Additive(is_additive);

	return true;
}

