// FUNCTION: BFME2 0x00149FD0 size=153 name=?Set_MeshModel_Flag@@YAXPAVRva00149FD0RenderObj@@IH@Z evidence=N:ledger tier=A
void Set_MeshModel_Flag(RenderObjClass *object, unsigned int flags, int enabled)
{
	// MeshClass's Class_ID is zero. The Get_Model returns a retained model.
	if (object->Class_ID() == 0) {
		MeshModelClass *model = object->_bfme_ro_v3()->Get_Model();
		model->Set_Flag(flags, enabled != 0);
		model->Release_Ref();
	} else {
		int count = object->Get_Num_Sub_Objects();
		for (int i = 0; i < count; ++i) {
			RenderObjClass *child = object->Get_Sub_Object(i);
			if (child) {
				Set_MeshModel_Flag(child, flags, enabled);
				child->Release_Ref();
			}
		}
	}
}


