// FUNCTION: BFME2 0x0014A630 size=103 name=?Scale@MeshClass@@UAEXM@Z evidence=N:ledger tier=A
void MeshClass::Scale(float factor)
{
	if (factor == 1.0f)
		return;

	Vector3 factors;
	factors.X = factors.Y = factors.Z = factor;
	Make_Unique();
	Model->Make_Geometry_Unique();
	Model->Scale(factors);
	Invalidate_Cached_Bounding_Volumes();

	// The container's bounds include this mesh.
	if (Container != NULL)
		Container->Update_Obj_Space_Bounding_Volumes();
}

// FUNCTION: BFME2 0x0014A6A0 size=101 name=?Scale@MeshClass@@UAEXMMM@Z evidence=N:ledger tier=A
void MeshClass::Scale(float sx, float sy, float sz)
{
	Vector3 factors(sx, sy, sz);
	Make_Unique();
	Model->Make_Geometry_Unique();
	Model->Scale(factors);
	Invalidate_Cached_Bounding_Volumes();

	if (Container != NULL)
		Container->Update_Obj_Space_Bounding_Volumes();
}

