// FUNCTION: BFME2 0x0014B5E0 size=104 name=?Intersect_AABox@MeshClass@@UAE_NAAVAABoxIntersectionTestClass@@@Z evidence=N:ledger tier=A
bool MeshClass::Intersect_AABox(AABoxIntersectionTestClass &boxtest)
{
	if (!(boxtest.CollisionType & Get_Collision_Type())) {
		return false;
	}

	// Transform the test into the mesh's object space (the OBBox form), then let the model's culling tree decide.
	Validate_Transform();
	Matrix3D world_to_obj;
	Transform.Get_Orthogonal_Inverse(world_to_obj);
	OBBoxIntersectionTestClass local_test(boxtest, world_to_obj);
	return Model->Intersect_OBBox(local_test);
}

// FUNCTION: BFME2 0x0014B650 size=366 name=?Update_Cached_Bounding_Volumes@MeshClass@@MBEXXZ evidence=N:ledger tier=A
void MeshClass::Update_Cached_Bounding_Volumes(void) const
{
	Get_Obj_Space_Bounding_Sphere(CachedBoundingSphere);

	Get_Transform().mulVector3(CachedBoundingSphere.Center);
	CachedBoundingSphere.Radius *= ObjectScale;

	// If we are camera-aligned or -oriented, we don't know which way we are facing at this point,
	// so the box we return needs to contain the sphere. Otherewise do the normal computation.
	if (Model->Get_Flag(MeshModelClass::ALIGNED) || Model->Get_Flag(MeshModelClass::ORIENTED)) {
		CachedBoundingBox.Center = CachedBoundingSphere.Center;
		CachedBoundingBox.Extent.Set(CachedBoundingSphere.Radius, CachedBoundingSphere.Radius, CachedBoundingSphere.Radius);
	} else {
		Get_Obj_Space_Bounding_Box(CachedBoundingBox);
		CachedBoundingBox.Transform(Get_Transform());
	}

	Validate_Cached_Bounding_Volumes();
}

// FUNCTION: BFME2 0x0014B7C0 size=62 name=?Get_Draw_Call_Count@MeshClass@@QBEHXZ evidence=N:ledger tier=A
int MeshClass::Get_Draw_Call_Count(void) const
{
	// One call per polygon renderer; before registration, one per texture.
	if (Model != NULL) {
		int count = Model->PolygonRendererList.Count();
		if (count > 0)
			return count;
		if (Model->MatInfo != NULL) {
			count = Model->MatInfo->Texture_Count();
			if (count > 0)
				return count;
		}
		return 1;
	}
	return 0;
}

