// FUNCTION: BFME2 0x0014BB20 size=66 name=?Set_Lighting_Environment@MeshClass@@QAEXPAVLightEnvironmentClass@@@Z evidence=N:ledger tier=A
void MeshClass::Set_Lighting_Environment(LightEnvironmentClass *light_env)
{
	if (light_env) {
		// An environment whose first byte is set is used where it is; any other is copied into the mesh.
		if (light_env->Get_Byte00()) {
			LightEnvironment = light_env;
		} else {
			LocalLightEnv = *light_env;
			LightEnvironment = &LocalLightEnv;
		}
	} else {
		LightEnvironment = NULL;
	}
}

